// Validate form data and calculate spaced repetition revision dates
const row = $json;

const name          = (row['Your Name']                      || '').trim();
const email         = (row['Your Email']                     || '').trim();
const studyDate     = (row['Today Date']                     || new Date().toISOString().split('T')[0]).trim();
const totalHours    = parseFloat(row['Total Study Hours Today']) || 0;
const subjectsHours = (row['Subjects and Hours']             || '').trim();
const topicsCovered = (row['Topics Covered']                 || '').trim();
const understanding = (row['Understanding Level']            || 'Good').trim();
const weakAreas     = (row['What You Struggled With']        || 'None').trim();
const weeklyTarget  = (row['Weekly Hours Target Per Subject']|| '').trim();
const notes         = (row['Any notes or concerns']          || '').trim();

if (!name)  throw new Error('Name is required.');
if (!email) throw new Error('Email is required.');
if (totalHours <= 0) throw new Error('Total study hours must be greater than 0.');
if (!topicsCovered || topicsCovered.length < 5) throw new Error('Topics Covered is required.');

// Calculate revision due dates (Ebbinghaus spaced repetition)
const base = new Date(studyDate);
const addDays = (d, n) => {
  const r = new Date(d);
  r.setDate(r.getDate() + n);
  return r.toISOString().split('T')[0];
};

const revDay1  = addDays(base, 1);
const revDay3  = addDays(base, 3);
const revDay7  = addDays(base, 7);
const revDay14 = addDays(base, 14);

const loggedAt = new Date().toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' });

return [{
  json: {
    name, email, studyDate, totalHours,
    subjectsHours, topicsCovered,
    understanding, weakAreas, weeklyTarget, notes,
    revDay1, revDay3, revDay7, revDay14,
    loggedAt
  }
}];

