// Parse AI JSON output safely
const resp    = $input.first().json;
const student = $('2. Code - Validate and Calc Revision Dates').first().json;

const raw = resp?.choices?.[0]?.message?.content || '';
let ai = {};

try {
  const cleaned = raw.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
  const s = cleaned.indexOf('{');
  const e = cleaned.lastIndexOf('}');
  if (s !== -1 && e !== -1) ai = JSON.parse(cleaned.substring(s, e + 1));
} catch (err) {
  ai = {
    score:        5,
    feedback:     'Good effort today! Keep studying consistently.',
    timeAnalysis: 'Review your weekly targets and adjust time accordingly.',
    weakAdvice:   'Spend extra time on weak topics tomorrow.',
    tomorrowPlan: 'Continue with pending topics and revise today material.',
    quiz:         ['What was the main concept you studied today?', 'Explain one formula or rule from today.', 'What will you revise first tomorrow?'],
    motivation:   'Consistency beats perfection. Every session counts!',
    weekTip:      'Try Pomodoro: 25 min focus then 5 min break.'
  };
}

const score = parseInt(ai.score) || 5;
const badge = score >= 8 ? 'Great' : score >= 6 ? 'Good' : 'Keep Going';
const scoreColor = score >= 8 ? '#27ae60' : score >= 6 ? '#f39c12' : '#e74c3c';
const quiz = Array.isArray(ai.quiz) ? ai.quiz : ['Review main concept from today.', 'Write key formulas.', 'Plan tomorrow revision.'];

return [{
  json: {
    ...student,
    score, badge, scoreColor,
    feedback:     ai.feedback     || '',
    timeAnalysis: ai.timeAnalysis || '',
    weakAdvice:   ai.weakAdvice   || '',
    tomorrowPlan: ai.tomorrowPlan || '',
    quiz,
    motivation:   ai.motivation   || '',
    weekTip:      ai.weekTip      || ''
  }
}];

// Find revision topics due today for this student + build complete email HTML
// This combines AI analysis (from node 4) with revision data (from node 5)

const allRows  = $input.all();
const student  = $('4. Code - Parse AI Response and Merge Data').first().json;
const today    = student.studyDate;
const myEmail  = student.email;

// Find rows due for revision today that belong to this student
const dueToday = allRows
  .filter(item => item.json.Email === myEmail)
  .filter(item => {
    const r = item.json;
    return (
      r['Rev Day1']  === today ||
      r['Rev Day3']  === today ||
      r['Rev Day7']  === today ||
      r['Rev Day14'] === today
    );
  })
  .map(item => {
    const r = item.json;
    let revType = '';
    if (r['Rev Day1']  === today) revType = '1st Revision (Day 1)';
    else if (r['Rev Day3']  === today) revType = '2nd Revision (Day 3)';
    else if (r['Rev Day7']  === today) revType = '3rd Revision (Day 7)';
    else if (r['Rev Day14'] === today) revType = 'Final Revision (Day 14)';
    return {
      studiedOn:    r['Date']           || '',
      subjects:     r['Subjects Today'] || r['Subjects and Hours'] || '',
      topics:       r['Topics Covered'] || '',
      revType
    };
  });

// Build revision HTML block
const revHtml = dueToday.length > 0
  ? dueToday.map(r =>
      '<div style="border:1px solid #ffe0b2;border-radius:6px;padding:12px;margin-bottom:8px;background:#fffde7;">'
      + '<div style="font-size:11px;color:#e65100;font-weight:700;margin-bottom:4px;">' + r.revType + ' - studied on ' + r.studiedOn + '</div>'
      + '<div style="font-size:13px;color:#333;">' + r.subjects + '</div>'
      + '<div style="font-size:12px;color:#666;margin-top:3px;">Topics: ' + r.topics + '</div>'
      + '</div>'
    ).join('')
  : '<p style="font-size:13px;color:#555;margin:0;">No revision due from previous sessions today. Today is a fresh start!</p>';

// Build quiz HTML
const quizHtml = student.quiz.map((q, i) =>
  '<p style="font-size:13px;color:#333;margin:0 0 8px;"><strong>Q' + (i+1) + '.</strong> ' + q + '</p>'
).join('');

// Build complete HTML email
const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>'
  + '<body style="font-family:Arial,sans-serif;max-width:680px;margin:0 auto;background:#f5f5f5;">'

  // Header
  + '<div style="background:#1a237e;padding:24px 28px;border-radius:8px 8px 0 0;">'
  + '<h1 style="color:#fff;font-size:19px;margin:0;">Daily Study Report</h1>'
  + '<p style="color:#c5cae9;font-size:13px;margin:6px 0 0;">' + student.name + ' &nbsp;|&nbsp; ' + student.studyDate + ' &nbsp;|&nbsp; ' + student.loggedAt + '</p>'
  + '</div>'

  // KPI bar
  + '<div style="background:#283593;padding:10px 24px;display:flex;gap:20px;flex-wrap:wrap;">'
  + '<span style="color:#fff;font-size:13px;">' + student.totalHours + ' hrs</span>'
  + '<span style="color:#fff;font-size:13px;">Score: <strong style="color:' + student.scoreColor + ';">' + student.score + '/10 (' + student.badge + ')</strong></span>'
  + '<span style="color:#c5cae9;font-size:12px;">' + student.understanding.split('-')[0].trim() + '</span>'
  + '</div>'

  + '<div style="background:#fff;padding:20px 24px;">'

  // AI Feedback
  + '<div style="background:#e8eaf6;border-left:4px solid #3f51b5;padding:14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 6px;font-size:14px;color:#1a237e;">Session Feedback</h2>'
  + '<p style="margin:0;font-size:14px;color:#333;line-height:1.7;">' + student.feedback + '</p>'
  + '</div>'

  // Time Analysis
  + '<div style="background:#f3f4f6;border-left:4px solid #607d8b;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 6px;font-size:14px;color:#1a237e;">Time vs Weekly Target</h2>'
  + '<p style="margin:0;font-size:13px;color:#444;line-height:1.6;">' + student.timeAnalysis + '</p>'
  + '</div>'

  // Weak Areas
  + '<div style="background:#fff8e1;border-left:4px solid #ffa000;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 6px;font-size:14px;color:#1a237e;">Weak Areas - Action Plan</h2>'
  + '<p style="margin:0;font-size:13px;color:#444;line-height:1.6;">' + student.weakAdvice + '</p>'
  + '</div>'

  // Tomorrow Plan
  + '<div style="background:#e8f5e9;border-left:4px solid #43a047;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 6px;font-size:14px;color:#1a237e;">Tomorrow Study Plan</h2>'
  + '<p style="margin:0;font-size:13px;color:#333;line-height:1.7;font-weight:500;">' + student.tomorrowPlan + '</p>'
  + '</div>'

  // Quiz
  + '<div style="background:#f3e5f5;border-left:4px solid #9c27b0;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 4px;font-size:14px;color:#1a237e;">Quick Recall Quiz</h2>'
  + '<p style="font-size:11px;color:#666;margin:0 0 10px;">Answer without looking at notes - this locks topics in memory.</p>'
  + quizHtml
  + '</div>'

  // Revision Due Today (from previous sessions)
  + '<div style="background:#fff3e0;border-left:4px solid #ff6f00;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 8px;font-size:14px;color:#1a237e;">Also Revise Today (from previous sessions)</h2>'
  + revHtml
  + '</div>'

  // Revision Schedule for today's topics
  + '<div style="background:#e3f2fd;border-left:4px solid #1e88e5;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
  + '<h2 style="margin:0 0 8px;font-size:14px;color:#1a237e;">Revision Schedule for Today Topics</h2>'
  + '<p style="font-size:11px;color:#555;margin:0 0 8px;">Based on the Ebbinghaus Forgetting Curve - revise at these dates to keep topics in long-term memory:</p>'
  + '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
  + '<tr style="background:#bbdefb;"><th style="padding:7px 10px;text-align:left;font-size:12px;color:#0d47a1;">Revision</th><th style="padding:7px 10px;text-align:left;font-size:12px;color:#0d47a1;">Date</th><th style="padding:7px 10px;text-align:left;font-size:12px;color:#0d47a1;">Why</th></tr>'
  + '<tr><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;">1st Revision</td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;"><strong>' + student.revDay1 + '</strong></td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;font-size:11px;color:#666;">Day+1 - 67% already forgotten without revision</td></tr>'
  + '<tr><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;">2nd Revision</td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;"><strong>' + student.revDay3 + '</strong></td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;font-size:11px;color:#666;">Day+3 - moving to long-term memory</td></tr>'
  + '<tr><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;">3rd Revision</td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;"><strong>' + student.revDay7 + '</strong></td><td style="padding:7px 10px;border-bottom:1px solid #e3f2fd;font-size:11px;color:#666;">Day+7 - consolidation in long-term memory</td></tr>'
  + '<tr><td style="padding:7px 10px;">Final Revision</td><td style="padding:7px 10px;"><strong>' + student.revDay14 + '</strong></td><td style="padding:7px 10px;font-size:11px;color:#666;">Day+14 - permanent retention secured</td></tr>'
  + '</table>'
  + '</div>'

  // Motivation + Weekly Tip
  + '<div style="background:#fce4ec;border-left:4px solid #e91e63;padding:11px 14px;border-radius:0 6px 6px 0;margin-bottom:12px;">'
  + '<p style="margin:0;font-size:13px;color:#333;font-style:italic;">' + student.motivation + '</p>'
  + '</div>'
  + '<div style="background:#f1f8e9;border-left:4px solid #7cb342;padding:10px 14px;border-radius:0 6px 6px 0;">'
  + '<p style="margin:0;font-size:13px;color:#444;">Tip: ' + student.weekTip + '</p>'
  + '</div>'

  + '</div>'

  // Footer
  + '<div style="background:#1a237e;padding:12px 24px;text-align:center;border-radius:0 0 8px 8px;">'
  + '<p style="color:#c5cae9;font-size:11px;margin:0;">Student Study Manager - n8n + ChatGPT AI | Morning reminder arrives at 7AM</p>'
  + '</div>'
  + '</body></html>';

return [{
  json: {
    ...student,
    dueRevisionCount: dueToday.length,
    htmlEmail: html,
    emailSubject: 'Study Report ' + student.score + '/10 - ' + student.studyDate + ' | ' + student.name
  }
}];

// Find revision topics due today per student and build morning reminder emails
const allRows = $input.all();
const today   = new Date().toISOString().split('T')[0];

// Group by student email
const studentMap = {};

allRows.forEach(item => {
  const r = item.json;
  if (!r.Email || !r.Date) return;

  const email = r.Email.trim();
  const name  = (r['Student Name'] || 'Student').trim();

  if (!studentMap[email]) {
    studentMap[email] = { email, name, dueToday: [], weekHours: 0 };
  }

  // Check revision dates
  [
    { col: 'Rev Day1',  label: '1st Revision (Day 1 - 67% already forgotten)' },
    { col: 'Rev Day3',  label: '2nd Revision (Day 3 - reinforcement)' },
    { col: 'Rev Day7',  label: '3rd Revision (Day 7 - long-term memory)' },
    { col: 'Rev Day14', label: 'Final Revision (Day 14 - permanent retention)' }
  ].forEach(rv => {
    if (r[rv.col] && r[rv.col].trim() === today) {
      studentMap[email].dueToday.push({
        studiedOn: r['Date'] || '',
        subjects:  r['Subjects Today'] || '',
        topics:    r['Topics Covered'] || '',
        label:     rv.label
      });
    }
  });

  // Count hours this week
  const rowDate = new Date(r.Date);
  const cutoff  = new Date(today);
  cutoff.setDate(cutoff.getDate() - 7);
  if (rowDate >= cutoff) {
    studentMap[email].weekHours += parseFloat(r['Total Hours'] || 0);
  }
});

// Build one result per student
return Object.values(studentMap)
  .filter(s => s.dueToday.length > 0)
  .map(s => {
    const revHtml = s.dueToday.map(r =>
      '<div style="border:1px solid #ffe0b2;border-radius:6px;padding:12px;margin-bottom:8px;background:#fffde7;">'
      + '<div style="font-size:11px;color:#e65100;font-weight:700;margin-bottom:4px;">' + r.label + '</div>'
      + '<div style="font-size:13px;color:#333;">Subjects: ' + r.subjects + '</div>'
      + '<div style="font-size:12px;color:#666;margin-top:3px;">Topics: ' + r.topics + '</div>'
      + '</div>'
    ).join('');

    const html = '<!DOCTYPE html><html><head><meta charset="utf-8"></head>'
      + '<body style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;background:#f5f5f5;">'
      + '<div style="background:#1b5e20;padding:22px 28px;border-radius:8px 8px 0 0;">'
      + '<h1 style="color:#fff;font-size:18px;margin:0;">Good Morning, ' + s.name + '!</h1>'
      + '<p style="color:#a5d6a7;font-size:13px;margin:6px 0 0;">' + today + ' &nbsp;|&nbsp; Hours this week: ' + s.weekHours.toFixed(1) + ' hrs</p>'
      + '</div>'
      + '<div style="background:#fff;padding:20px 24px;">'
      + '<div style="background:#fff3e0;border-left:4px solid #ff6f00;padding:14px;border-radius:0 6px 6px 0;margin-bottom:16px;">'
      + '<h2 style="margin:0 0 8px;font-size:15px;color:#1b5e20;">' + s.dueToday.length + ' Topic(s) Due for Revision TODAY</h2>'
      + '<p style="font-size:12px;color:#666;margin:0 0 12px;">Revise these now before starting new topics. It takes only 15-20 minutes and prevents forgetting.</p>'
      + revHtml
      + '</div>'
      + '<div style="background:#e3f2fd;border-left:4px solid #1e88e5;padding:12px 14px;border-radius:0 6px 6px 0;margin-bottom:12px;">'
      + '<h2 style="margin:0 0 6px;font-size:13px;color:#1b5e20;">How to revise in 15 minutes</h2>'
      + '<ul style="margin:0;padding-left:18px;font-size:13px;color:#444;line-height:1.9;">'
      + '<li>Close the book - write main points from memory</li>'
      + '<li>Check what you missed and read only those</li>'
      + '<li>Solve 2-3 practice questions per topic</li>'
      + '<li>Mark as done then start new topics</li>'
      + '</ul>'
      + '</div>'
      + '<div style="background:#f1f8e9;border-left:4px solid #7cb342;padding:10px 14px;border-radius:0 6px 6px 0;">'
      + '<p style="margin:0;font-size:13px;color:#444;">Fill your study log tonight and tomorrow morning reminder will be ready automatically.</p>'
      + '</div>'
      + '</div>'
      + '<div style="background:#1b5e20;padding:12px 24px;text-align:center;border-radius:0 0 8px 8px;">'
      + '<p style="color:#a5d6a7;font-size:11px;margin:0;">Student Study Manager - Morning Revision Reminder</p>'
      + '</div>'
      + '</body></html>';

    return {
      json: {
        email:       s.email,
        name:        s.name,
        weekHours:   s.weekHours,
        dueCount:    s.dueToday.length,
        htmlEmail:   html,
        emailSubject: s.dueToday.length + ' Topics Due for Revision Today - ' + today + ' | ' + s.name
      }
    };
  });
